using GastricCancerDetection.Infrastructure.Persistence; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace GastricCancerDetection.Api.Controllers; [ApiController][Route("api/noncoding-hotspots")] public class NonCodingHotspotsController:ControllerBase { private readonly GastricCancerDbContext _db; public NonCodingHotspotsController(GastricCancerDbContext db)=>_db=db; [HttpGet] public async Task<IActionResult> Get([FromQuery]int? runId=null,[FromQuery]string? region=null){var q=_db.NonCodingVariants.AsNoTracking();if(runId.HasValue)q=q.Where(x=>x.AnalysisRunId==runId);if(!string.IsNullOrWhiteSpace(region))q=q.Where(x=>x.Region==region);return Ok(await q.OrderByDescending(x=>x.Recurrence).Take(1000).ToListAsync());} }
